/* HAMU Projects (projects.php + proje/FTP) — robust split build (readable) */
(function (w, d) {
  "use strict";

  // --- Safe fallbacks / globals we depend on from main.js
  const has = (x) => typeof x !== "undefined" && x !== null;
  const T = (k, fb) => { try { return (w.l_js__ && w.l_js__(k)) || (fb ?? k); } catch { return fb ?? k; } };
  const debounce = w.debounce || function (fn, ms = 300) { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
  const setCookie = w.setCookie || function (k, v, days = 365) {
    try {
      const dte = new Date(); dte.setTime(dte.getTime() + days * 864e5);
      const secure = location.protocol === "https:" ? "; Secure; SameSite=Lax" : "";
      document.cookie = `${encodeURIComponent(k)}=${encodeURIComponent(v)}; expires=${dte.toUTCString()}; path=/${secure}`;
    } catch {}
  };
  const getCookie = w.getCookie || function (k) {
    try {
      const name = encodeURIComponent(k) + "=";
      return (document.cookie.split(";").map(s=>s.trim()).find(c=>c.indexOf(name)===0) || "").slice(name.length) || "";
    } catch { return ""; }
  };
  const HAMU_API_URL = w.HAMU_API_URL || "/?api=config&_prj=1";
  const bsShow = w.bsShow || function (elOrId) {
    const el = typeof elOrId === "string" ? d.getElementById(elOrId) : elOrId;
    if (!el) return;
    try {
      if (w.bootstrap?.Modal) w.bootstrap.Modal.getOrCreateInstance(el).show();
      else { el.classList.add("show"); el.style.display = "block"; el.removeAttribute("aria-hidden"); }
    } catch {}
  };
  const getCsrfToken = w.getCsrfToken || function () {
    const m = d.querySelector('meta[name="csrf-token"]'); if (m?.content) return m.content;
    const i = d.querySelector('input[name="csrf_token"]'); if (i?.value) return i.value;
    return w.CSRF_TOKEN || "";
  };
  const postProject = w.postProject || function (action, data = {}, files = null) {
    const fd = new FormData();
    fd.append("_hamu_project", "1");
    fd.append("action", action);
    fd.append("csrf_token", getCsrfToken());
    Object.entries(data).forEach(([k, v]) => { if (v !== undefined && v !== null) fd.append(k, v); });
    if (files && typeof files === "object") Object.entries(files).forEach(([k, v]) => v && fd.append(k, v));
    return fetch(HAMU_API_URL, { method: "POST", body: fd, credentials: "same-origin", headers: { "X-Requested-With": "XMLHttpRequest" } })
      .then(r => { if (!r.ok) throw new Error("Network " + r.status); return r.json().catch(()=>({})); })
      .then(j => { if (j && (j.ok || j.success || j.status === "ok")) return j; throw new Error(j?.msg || j?.error || T("unexpected_response","Unexpected response")); })
      .catch(e => ({ success: false, message: e.message || T("request_error","Request error") }));
  };

  // ----------------------------
  //  Gizli klasör filtresi
  // ----------------------------
  function applyHiddenFilter() {
    const hid = d.getElementById("fltHidden");
    const fromCookie = getCookie("showHiddenProjects") === "1";
    const showHidden = hid ? !!hid.checked : fromCookie;

    d.querySelectorAll(".folder-actions[data-is-hidden]").forEach((actions) => {
      const raw = String(actions.getAttribute("data-is-hidden") || "").toLowerCase();
      const isHidden = raw === "1" || raw === "true" || raw === "yes";
      const card = actions.closest(".col") || actions.closest(".folder") || actions.closest(".project-card");
      if (!card) return;
      card.style.display = !showHidden && isHidden ? "none" : "";
    });
  }
  w.applyHiddenFilter = applyHiddenFilter; // export (liste sayfası da çağırıyor)

  // ----------------------------
  //  Liste Filter & Search
  // ----------------------------
  (function () {
    if (typeof window === "undefined") return;

    const qs = new URLSearchParams(window.location.search);
    const qInput = d.getElementById("qInput");
    if (qInput) {
      qInput.addEventListener("input", debounce(function () {
        const val = qInput.value.trim();
        if (val) qs.set("q", val); else qs.delete("q");
        qs.set("page", "1");
        window.location.search = qs.toString();
      }, 300));
    }

    d.addEventListener("DOMContentLoaded", () => {
      const fav = d.getElementById("fltFav");
      const hidx = d.getElementById("fltHasIndex");

      const favCookieOn = getCookie("onlyFavorites") === "1";
      const hasCookieOn = getCookie("onlyHasIndex") === "1";

      const url = new URL(location.href);
      const urlHasFav = url.searchParams.has("fav");
      const urlHasHas = url.searchParams.has("hasindex");

      if (favCookieOn || hasCookieOn) {
        d.querySelectorAll('a[href="/"], a[href$="/"], a.home-link, .logo a').forEach((a) => {
          try {
            const u = new URL(a.getAttribute("href"), location.origin);
            if (favCookieOn && !u.searchParams.has("fav")) u.searchParams.set("fav", "1");
            if (hasCookieOn && !u.searchParams.has("hasindex")) u.searchParams.set("hasindex", "1");
            a.setAttribute("href", u.pathname + (u.searchParams.toString() ? "?" + u.searchParams.toString() : ""));
          } catch {}
        });
      }

      if (!sessionStorage.getItem("filtersRedirected") && ((favCookieOn && !urlHasFav) || (hasCookieOn && !urlHasHas))) {
        sessionStorage.setItem("filtersRedirected", "1");
        if (favCookieOn) url.searchParams.set("fav", "1");
        if (hasCookieOn) url.searchParams.set("hasindex", "1");
        url.searchParams.set("page", "1");
        location.search = url.searchParams.toString();
        return;
      }

      if (fav && favCookieOn) fav.checked = true;
      if (hidx && hasCookieOn) hidx.checked = true;

      [fav, hidx].forEach((el) => {
        if (!el) return;
        el.addEventListener("change", () => {
          const p = new URLSearchParams(location.search);
          if (fav) {
            if (fav.checked) { p.set("fav", "1"); setCookie("onlyFavorites", "1", 365); }
            else { p.delete("fav"); setCookie("onlyFavorites", "0", 365); }
          }
          if (hidx) {
            if (hidx.checked) { p.set("hasindex", "1"); setCookie("onlyHasIndex", "1", 365); }
            else { p.delete("hasindex"); setCookie("onlyHasIndex", "0", 365); }
          }
          p.set("page", "1");
          location.search = p.toString();
        });
      });
    });

    // Hidden toggle (cookie only)
    const hid = d.getElementById("fltHidden");
    if (hid) {
      hid.checked = getCookie("showHiddenProjects") === "1";
      try { applyHiddenFilter(); } catch {}
      hid.addEventListener("change", function () {
        setCookie("showHiddenProjects", hid.checked ? "1" : "0", 365);
        try { applyHiddenFilter(); } catch {}
        // server-side liste için
        window.location.reload();
      });
    }
  })();

  // ----------------------------
  //  Proje kartı hızlı aksiyonları
  // ----------------------------
  (function () {
    const isMobile = () => w.matchMedia && w.matchMedia("(max-width: 992px)").matches;

    d.addEventListener("click", async function (e) {
      const btn = e.target.closest(".folder-actions .btn-icon, .js-proj-cog, .mobile-cog");
      if (!btn) return;

      e.preventDefault(); e.stopPropagation();

      // sadece menüyü aç/kapat
      if (btn.matches(".js-proj-cog, .mobile-cog")) {
        const card = btn.closest(".folder, .project-card");
        const menu = card?.querySelector(".folder-actions");
        if (menu) {
          const open = menu.classList.toggle("show");
          card.classList.toggle("actions-open", open);
        }
        return;
      }

      const actions = btn.closest(".folder-actions");
      if (!actions) return;
      const folder = actions.dataset.folder || "";
      const action = btn.getAttribute("data-action");

      try {
        switch (action) {
          case "settings": {
            if (folder && typeof w.openProjectSettingsModal === "function") {
              await w.openProjectSettingsModal(folder);
            } else {
              const modal = d.getElementById("projectSettingsModal");
              if (modal) bsShow(modal);
            }
            break;
          }
          case "fav": {
            const res = await postProject("project_favorite_toggle", { folder });
            if (!res || res.success === false) return alert(T("favorite_update_failed", "Favorite update failed"));
            const nowFav = (res.favorite === true || res.favorite === 1 || res.favorite === "1");
            const iTag = btn.querySelector("i");
            if (iTag) { iTag.classList.toggle("fa-solid", nowFav); iTag.classList.toggle("fa-regular", !nowFav); }
            const onlyFav = (new URLSearchParams(location.search).get("fav") === "1");
            if (onlyFav && !nowFav) {
              const card = actions.closest(".col, .folder, .project-card");
              if (card) card.remove();
              const grid = d.querySelector(".projects-grid, .row, .grid");
              if (!grid || !grid.querySelector(".project-card, .folder, .col")) location.reload();
            }
            break;
          }
          case "hide": {
            const res = await postProject("project_hide", { folder: folder.replace(/^\.+/, "") });
            if (!res || res.success === false) return alert(T("hide_failed", "Hide failed"));
            location.reload();
            break;
          }
          case "unhide": {
            const res = await postProject("project_unhide", { folder: folder.startsWith(".") ? folder : "." + folder });
            if (!res || res.success === false) return alert(T("unhide_failed", "Unhide failed"));
            location.reload();
            break;
          }
          case "delete": {
            if (!confirm(T("confirm_delete_perm", "Delete permanently?").replace("%s", folder))) return;
            if (!confirm(T("confirm_irreversible", "This cannot be undone"))) return;
            const res = await postProject("delete_project", { folder });
            if (!res || res.success === false) return alert(res?.message || T("delete_failed", "Delete failed"));
            location.reload();
            break;
          }
          case "rename": {
            const cur = folder;
            const next = prompt(T("prompt_new_folder_name", "New folder name"), cur) || "";
            const newName = next.trim();
            if (!newName || newName === cur) return;
            if (!/^[A-Za-z0-9._-]+$/.test(newName)) { alert(T("invalid_name", "Invalid name")); return; }
            try {
              const res = await postProject("project_rename", { old: cur, new: newName, folder: cur, new_name: newName, new_folder: newName, target: newName });
              if (!res || res.success === false) return alert(T("rename_failed", "Rename failed"));
              location.search = new URLSearchParams({ project: newName }).toString();
            } catch (err) {
              console.error(err);
              alert(T("network_error", "Network error"));
            }
            break;
          }
        }
      } catch (err) {
        console.error(err);
        alert(err.message || T("op_failed", "Operation failed"));
      } finally {
        if (isMobile()) {
          const card = btn.closest(".folder, .project-card");
          card?.classList.remove("actions-open");
          actions?.classList.remove("show");
        }
      }
    }, true);

    // menü dışına tıklama / ESC kapatma
    d.addEventListener("click", function (e) {
      const open = d.querySelector(".folder.actions-open, .project-card.actions-open");
      if (open && !e.target.closest(".folder, .project-card")) {
        open.classList.remove("actions-open");
        open.querySelector(".folder-actions")?.classList.remove("show");
      }
    });
    d.addEventListener("keydown", function (e) {
      if (e.key === "Escape") {
        d.querySelectorAll(".folder.actions-open, .project-card.actions-open").forEach(el => el.classList.remove("actions-open"));
        d.querySelectorAll(".folder-actions.show").forEach(m => m.classList.remove("show"));
      }
    });
  })();

  // ----------------------------
  //  Kapak önizleme utils
  // ----------------------------
  function chainImage(imgEl, urls) {
    if (!imgEl) return;
    let i = 0;
    const next = () => {
      if (i >= urls.length) return;
      imgEl.onerror = () => { i++; next(); };
      imgEl.src = urls[i];
    };
    next();
  }
  function setCoverPreviewFromList(urls) { const img = d.getElementById("psmCoverPreview"); if (!img) return; chainImage(img, urls); }
  function updateCoverPreviewSmart(folder, projectIconPath) {
    const clean = String(folder || "").replace(/^\.\//, "").replace(/^\//, "");
    const list = [];
    if (projectIconPath) list.push(projectIconPath);
    list.push(`/${clean}/index.png`);
    list.push(`/.hamu/assets/images/efolder.png`);
    list.push(`/.hamu/assets/images/folder.png`);
    setCoverPreviewFromList(list);
  }
  // export used by openProjectSettingsModal
  w.updateCoverPreviewSmart = updateCoverPreviewSmart;

  // ----------------------------
  //  Kalıcı silme doğrulama
  // ----------------------------
  (function () {
    const delInp = d.getElementById("deleteConfirmInput");
    const delBtn = d.getElementById("btnConfirmDelete");
    if (!delInp || !delBtn) return;
    delInp.addEventListener("input", function () {
      const phrase = (T("delete_confirm_phrase", "DELETE"));
      delBtn.disabled = this.value.trim().toUpperCase() !== phrase.toUpperCase();
    });
  })();

  // ----------------------------
  //  Proje Ayarları Modal — submit (RENAME + META + FTP)
  // ----------------------------
  d.addEventListener("DOMContentLoaded", function () {
    const form = d.getElementById("projectSettingsForm");
    const file = d.getElementById("psmCover");
    const img = d.getElementById("psmCoverPreview");
    const fav = d.getElementById("psmFav");
    const favBtn = d.getElementById("psmFavBtn");

    if (file && img) {
      file.addEventListener("change", function () {
        const f = this.files && this.files[0]; if (!f) return;
        const r = new FileReader();
        r.onload = (e) => { img.src = e.target.result; };
        r.readAsDataURL(f);
      });
    }
    function syncFavBtn() {
      if (!fav || !favBtn) return;
      favBtn.classList.toggle("btn-secondary", fav.checked);
      favBtn.classList.toggle("btn-outline-secondary", !fav.checked);
    }
    fav?.addEventListener("change", syncFavBtn);

    if (!form) return;
    form.addEventListener("submit", async function (e) {
      e.preventDefault();

      const folderInp = d.getElementById("psmFolder");
      let folder = folderInp ? (folderInp.value || "").trim() : "";
      const newName = (d.getElementById("psmNewName")?.value || "").trim();

      // 1) RENAME
      if (newName && newName !== folder) {
        try {
          const fdRen = new FormData();
          fdRen.append("_hamu_project", "1");
          fdRen.append("action", "project_rename");
          fdRen.append("old", folder);
          fdRen.append("new", newName);
          fdRen.append("csrf_token", getCsrfToken());
          const resRen = await fetch(HAMU_API_URL, { method: "POST", body: fdRen, credentials: "same-origin", headers: { "X-Requested-With": "XMLHttpRequest" } });
          const jRen = await resRen.json();
          if (!jRen || jRen.success === false) { alert(jRen?.message || T("rename_failed", "Rename failed")); return; }
          folder = newName;
          if (folderInp) folderInp.value = newName;
          const n = d.getElementById("psmFolderName"); if (n) n.textContent = newName;
        } catch (err) {
          console.error(err);
          alert(T("network_error_rename", "Network error (rename)"));
          return;
        }
      }

      // 2) META
      try {
        const fdMeta = new FormData(form);
        fdMeta.append("_hamu_project", "1");
        if (!fdMeta.get("action")) fdMeta.set("action", "project_meta_write");
        fdMeta.set("csrf_token", getCsrfToken());
        if (folder) fdMeta.set("folder", folder);
        const resMeta = await fetch(HAMU_API_URL, { method: "POST", body: fdMeta, credentials: "same-origin", headers: { "X-Requested-With": "XMLHttpRequest" } });
        const jMeta = await resMeta.json();
        if (!jMeta || jMeta.success === false) { alert(T("save_error_meta", "Save meta failed")); return; }
      } catch (e2) {
        console.error(e2);
        alert(T("network_error_meta", "Network error (meta)"));
        return;
      }

      // 3) FTP
      try {
        const gv = (id, nameFallback) => {
          const el = d.getElementById(id) || (nameFallback ? d.querySelector(`[name="${nameFallback}"]`) : null);
          if (!el) return "";
          return el.type === "checkbox" ? (el.checked ? "true" : "false") : (el.value || "");
        };
        const fdFtp = new FormData();
        fdFtp.append("_hamu_project", "1");
        fdFtp.append("action", "project_ftp_write");
        if (folder) fdFtp.append("folder", folder);
        fdFtp.append("csrf_token", getCsrfToken());
        fdFtp.append("ftp_host", gv("psmFtpHost", "ftp_host"));
        fdFtp.append("ftp_port", gv("psmFtpPort", "ftp_port") || "21");
        fdFtp.append("ftp_ssl", gv("psmFtpSSL", "ftp_ssl"));
        fdFtp.append("ftp_user", gv("psmFtpUser", "ftp_user"));
        const passInput = d.getElementById("psmFtpPass");
        const passVal = gv("psmFtpPass", "ftp_pass").trim();
        if (passInput && passVal && passVal !== passInput.placeholder) fdFtp.append("ftp_pass", passVal);
        fdFtp.append("ftp_folder", gv("psmFtpFolder", "ftp_folder"));
        fdFtp.append("host_url", gv("psmHostUrl", "host_url"));
        fdFtp.append("description", gv("psmDesc", "description"));
        fdFtp.append("download_folder", gv("psmDown", "download_folder"));
        const resFtp = await fetch(HAMU_API_URL, { method: "POST", body: fdFtp, credentials: "same-origin", headers: { "X-Requested-With": "XMLHttpRequest" } });
        const jFtp = await resFtp.json();
        if (!jFtp || jFtp.success === false) { alert(T("save_error_ftp", "Save FTP failed")); return; }
      } catch (e3) {
        console.error(e3);
        alert(T("network_error_ftp", "Network error (FTP)"));
        return;
      }

      if (w.bootstrap?.Modal) {
        const modalEl = d.getElementById("projectSettingsModal");
        w.bootstrap.Modal.getOrCreateInstance(modalEl).hide();
      }
      setTimeout(() => location.reload(), 150);
    });
  });

  // ----------------------------
  //  Proje Ayarları Modal — Açılış/Okuma
  // ----------------------------
  w.openProjectSettingsModal = async function (folder) {
    const titleEl = d.getElementById("psmFolderName");
    const folderInp = d.getElementById("psmFolder");
    if (titleEl) titleEl.textContent = folder || "";
    if (folderInp) folderInp.value = folder || "";
    const rn = d.getElementById("psmNewName"); if (rn) rn.value = folder || "";

    let meta = null;
    try {
      const fd = new FormData();
      fd.append("_hamu_project", "1");
      fd.append("action", "project_meta_read");
      fd.append("folder", folder);
      fd.append("csrf_token", getCsrfToken());
      const res = await fetch(HAMU_API_URL, { method: "POST", body: fd, credentials: "same-origin", headers: { "X-Requested-With": "XMLHttpRequest" } });
      const json = await res.json();
      if (json?.success && json.meta) {
        meta = json.meta;
        const fav = d.getElementById("psmFav"); if (fav) fav.checked = !!meta.favorite;
        const bt = d.getElementById("psmBadgeText"); if (bt) bt.value = meta.badge_text || "";
        const bc = d.getElementById("psmBadgeColor"); if (bc) bc.value = meta.badge_color || "";
        const tg = d.getElementById("psmTags");
        if (tg) tg.value = Array.isArray(meta.tags) ? meta.tags.join(", ") : (meta.tags || "");
        const ftp = meta.ftp || {};
        const mapNoPass = {
          psmFtpHost: "ftp_host", psmFtpPort: "ftp_port", psmFtpSSL: "ftp_ssl", psmFtpUser: "ftp_user",
          psmFtpFolder: "ftp_folder", psmHostUrl: "host_url", psmDesc: "description", psmDown: "download_folder"
        };
        for (const [id, key] of Object.entries(mapNoPass)) {
          const el = d.getElementById(id); if (!el) continue;
          if (el.type === "checkbox") el.checked = (String(ftp[key] || "").toLowerCase() === "true" || ftp[key] === "1");
          else el.value = ftp[key] || "";
        }
        const passEl = d.getElementById("psmFtpPass");
        if (passEl) {
          const hasPass = !!ftp?.has_password || !!ftp?.ftp_pass;
          passEl.value = ""; passEl.placeholder = hasPass ? "••••••" : "";
          passEl.setAttribute("data-has-pass", hasPass ? "1" : "0");
        }
      }
    } catch (e) { console.error("project_meta_read error:", e); }

    const iconPath = meta && meta.project_icon ? meta.project_icon : "";
    try { updateCoverPreviewSmart(folder, iconPath); } catch (e) { console.warn("updateCoverPreviewSmart missing?", e); }

    (function syncFavOnce() {
      const fav = d.getElementById("psmFav"); const favBtn = d.getElementById("psmFavBtn");
      if (fav && favBtn) {
        favBtn.classList.toggle("btn-secondary", fav.checked);
        favBtn.classList.toggle("btn-outline-secondary", !fav.checked);
        fav.removeEventListener("change", w.__favSyncHandler || (() => {}));
        const handler = () => {
          favBtn.classList.toggle("btn-secondary", fav.checked);
          favBtn.classList.toggle("btn-outline-secondary", !fav.checked);
        };
        fav.addEventListener("change", handler);
        w.__favSyncHandler = handler;
      }
    })();

    const modal = d.getElementById("projectSettingsModal");
    if (modal) w.bootstrap?.Modal.getOrCreateInstance(modal).show();
  };

  // ----------------------------
  //  Badge önizleme
  // ----------------------------
  const BOOTSTRAP_COLORS = new Set(["primary", "secondary", "success", "danger", "warning", "info", "light", "dark"]);
  function applyBadgePreview(text, color) {
    const el = d.getElementById("psmBadgePreview"); if (!el) return;
    el.textContent = text || T("preview", "Preview");
    el.className = "badge";
    if (color && BOOTSTRAP_COLORS.has(color)) {
      el.classList.add("bg-" + color); el.style.backgroundColor = ""; el.style.color = "";
    } else if (color && /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(color)) {
      el.style.backgroundColor = color;
      try {
        const hex = color.replace("#", "");
        const r = parseInt(hex.length === 3 ? hex[0] + hex[0] : hex.slice(0, 2), 16);
        const g = parseInt(hex.length === 3 ? hex[1] + hex[1] : hex.slice(2, 4), 16);
        const b = parseInt(hex.length === 3 ? hex[2] + hex[2] : hex.slice(4, 6), 16);
        const lum = 0.299 * r + 0.587 * g + 0.114 * b;
        el.style.color = lum > 160 ? "#111" : "#fff";
      } catch { el.style.color = "#fff"; }
    } else {
      el.classList.add("bg-secondary"); el.style.backgroundColor = ""; el.style.color = "";
    }
  }
  function wireBadgePreview() {
    const txt = d.getElementById("psmBadgeText");
    const sel = d.getElementById("psmBadgeColor");
    const update = () => applyBadgePreview(txt?.value || "", sel?.value || "");
    if (txt) txt.addEventListener("input", update);
    if (sel) sel.addEventListener("change", update);
    update();
  }
  d.addEventListener("DOMContentLoaded", wireBadgePreview);

  // ----------------------------
  //  Sıralama cookie
  // ----------------------------
  d.addEventListener("click", function (e) {
    const a = e.target.closest(".dropdown-menu [data-sort]");
    if (!a) return;
    try {
      const val = a.getAttribute("data-sort") || "name_asc";
      document.cookie = "sortProjects=" + encodeURIComponent(val) + "; path=/; max-age=" + (365 * 24 * 60 * 60);
    } catch {}
  }, true);

  // ----------------------------
  //  FTP parola göster/gizle (FTP sayfası)
  // ----------------------------
  d.getElementById("btnReveal")?.addEventListener("click", function () {
    const inp = d.getElementById("ftpPassInput"); if (!inp) return;
    if (inp.type === "password") { inp.type = "text"; this.textContent = T('hide', 'Hide'); }
    else { inp.type = "password"; this.textContent = (typeof w.l_js__ === "function" ? w.l_js__("show") : "göster"); }
  });

  // ----------------------------
  //  Dosya Yöneticisi iFrame (FTP sayfası)
  // ----------------------------
  (function () {
    const iframe = d.getElementById("FM_iframe");
    const btn = d.getElementById("folderDropdownButton");
    if (!iframe || !btn) return;

    function ensureLabelSpan() {
      let label = btn.querySelector(".dropdown-label");
      if (!label) { label = d.createElement("span"); label.className = "dropdown-label"; btn.appendChild(label); }
      return label;
    }
    function reloadIframe(updateParams = {}) {
      const url = new URL(iframe.src, w.location.origin);
      url.pathname = "/index.php";
      url.searchParams.set("p", "fmi");
      url.searchParams.set("iframe", "1");
      const hasFUpdate = Object.prototype.hasOwnProperty.call(updateParams, "f");
      if (!hasFUpdate) {
        const currentF = url.searchParams.get("f") || "";
        if (currentF) url.searchParams.set("f", currentF);
        else url.searchParams.delete("f");
      }
      for (const [k, v] of Object.entries(updateParams)) {
        if (v === null || v === undefined || v === "") url.searchParams.delete(k);
        else url.searchParams.set(k, v);
      }
      iframe.src = url.pathname + "?" + url.searchParams.toString();
    }
    let reloadTimer;
    const reloadDebounced = (params = {}) => { clearTimeout(reloadTimer); reloadTimer = setTimeout(() => reloadIframe(params), 180); };

    d.querySelectorAll('.dropdown-item[extra-target="iframe"]').forEach(function (item) {
      item.addEventListener("click", function (e) {
        e.preventDefault();
        const label = ensureLabelSpan();
        const itemText = (this.getAttribute("data-label") || this.textContent || "").trim();
        const projText = typeof w.l_js__ === "function" ? w.l_js__("project") : (typeof w.PROJECT_LABEL_PHP !== "undefined" ? w.PROJECT_LABEL_PHP : "Project");
        if (label) label.textContent = `${projText}: ${itemText}`;

        const menu = this.closest(".dropdown-menu") || d;
        menu.querySelectorAll('.dropdown-item[extra-target="iframe"].active').forEach((el) => el.classList.remove("active"));
        this.classList.add("active");

        const folderEncoded = this.getAttribute("data-folder") || "";
        reloadDebounced({ f: folderEncoded });
      });
    });

    w.addEventListener("DOMContentLoaded", function () {
      const url = new URL(iframe.src, w.location.origin);
      const currentF = url.searchParams.get("f") || "";
      const label = ensureLabelSpan();

      let matched = false; let selectedText = "";
      d.querySelectorAll('.dropdown-item[extra-target="iframe"]').forEach(function (item) {
        const f = item.getAttribute("data-folder") || "";
        if (f === currentF) {
          matched = true; item.classList.add("active");
          selectedText = (item.getAttribute("data-label") || item.textContent || "").trim();
        } else item.classList.remove("active");
      });

      const projText = typeof w.l_js__ === "function" ? w.l_js__("project") : (typeof w.PROJECT_LABEL_PHP !== "undefined" ? w.PROJECT_LABEL_PHP : "Project");
      if (label) {
        if (matched) label.textContent = `${projText}: ${selectedText}`;
        else label.textContent = (typeof w.l_js__ === "function" ? w.l_js__("all_projects") : (typeof w.ALL_PROJECTS_PHP !== "undefined" ? w.ALL_PROJECTS_PHP : "All Projects"));
      }

      // cookie → switch sync
      const hideColsEl = d.getElementById("hideColsSwitch");
      const showHiddenEl = d.getElementById("showHiddenSwitch");
      const errorReportEl = d.getElementById("errorReportingSwitch");
      const hideColsCookie = getCookie("hide_cols");
      const showHiddenCookie = getCookie("showHiddenFM");
      const errorReportCookie = getCookie("error_reporting");
      if (hideColsEl) hideColsEl.checked = hideColsCookie === "true";
      if (showHiddenEl) showHiddenEl.checked = showHiddenCookie === "true";
      if (errorReportEl) errorReportEl.checked = errorReportCookie === "true";
    });

    w.addEventListener("languageData:ready", function () {
      const label = ensureLabelSpan(); if (!label) return;
      const active = d.querySelector('.dropdown-item[extra-target="iframe"].active');
      if (active) {
        const itemText = (active.getAttribute("data-label") || active.textContent || "").trim();
        const projText = typeof w.l_js__ === "function" ? w.l_js__("project") : (typeof w.PROJECT_LABEL_PHP !== "undefined" ? w.PROJECT_LABEL_PHP : "Project");
        label.textContent = `${projText}: ${itemText}`;
      } else {
        label.textContent = (typeof w.l_js__ === "function" ? w.l_js__("all_projects") : (typeof w.ALL_PROJECTS_PHP !== "undefined" ? w.ALL_PROJECTS_PHP : "All Projects"));
      }
    }, { once: true });

    const themeSwitch = d.getElementById("mySwitch");
    themeSwitch?.addEventListener("change", function () {
      const newTheme = this.checked ? "dark" : "light";
      reloadDebounced({ theme: newTheme });
    });

    const hideColsEl = d.getElementById("hideColsSwitch");
    const showHiddenEl = d.getElementById("showHiddenSwitch");
    const errorReportEl = d.getElementById("errorReportingSwitch");
    if (hideColsEl) hideColsEl.addEventListener("change", function () { setCookie("hide_cols", this.checked ? "true" : "false"); reloadDebounced(); });
    if (showHiddenEl) showHiddenEl.addEventListener("change", function () { setCookie("showHiddenFM", this.checked ? "true" : "false"); reloadDebounced(); });
    if (errorReportEl) errorReportEl.addEventListener("change", function () { setCookie("error_reporting", this.checked ? "true" : "false"); reloadDebounced(); });
  })();

  // ----------------------------
  //  Data-toggle (koşullu alanlar)
  // ----------------------------
  function bindDataToggles() {
    const groups = d.querySelectorAll("section.db-toggle");
    function getRadioValueInSection(section, radioSelector, defVal) {
      if (!radioSelector) return null;
      const checked = section.querySelector(`${radioSelector}:checked`);
      if (checked) return checked.value;
      if (defVal != null) return defVal;
      const first = section.querySelector(radioSelector);
      return first ? first.value : null;
    }
    function allEnabledByIdsCsv(idsCsv) {
      if (!idsCsv) return true;
      const ids = idsCsv.split(",").map(s => s.trim()).filter(Boolean);
      if (!ids.length) return true;
      return ids.every(id => {
        const el = d.getElementById(id);
        return el ? !!el.checked : false;
      });
    }
    function applyGroup(section) {
      const enabledIdsCsv = section.getAttribute("data-enabled");
      const radioSel = section.getAttribute("data-radio");
      const defVal = section.getAttribute("data-default") ?? null;
      const hideClass = section.getAttribute("data-hide-class") || "hideS";

      const enabled = allEnabledByIdsCsv(enabledIdsCsv);
      const value = getRadioValueInSection(section, radioSel, defVal);
      const valuesArr = (value ?? "").split(",").map(s => s.trim()).filter(Boolean);

      const targets = section.querySelectorAll("[data-show-when], [data-switch]");
      targets.forEach(el => {
        const rule = (el.getAttribute("data-show-when") || "*").trim();
        const ruleArr = rule.split(",").map(s => s.trim()).filter(Boolean);
        const switchIds = el.getAttribute("data-switch") || "";
        const switchesOk = allEnabledByIdsCsv(switchIds);
        const match = rule === "*" || ruleArr.some(r => valuesArr.includes(r));
        const show = enabled && switchesOk && match;
        el.classList.toggle(hideClass, !show);
      });
    }
    function attach(section) {
      const enabledIdsCsv = section.getAttribute("data-enabled");
      const radioSel = section.getAttribute("data-radio");

      if (enabledIdsCsv) {
        enabledIdsCsv.split(",").map(s => s.trim()).filter(Boolean).forEach(id => {
          d.getElementById(id)?.addEventListener("change", () => applyGroup(section));
        });
      }
      if (radioSel) {
        section.querySelectorAll(radioSel).forEach(el => {
          el.addEventListener("change", () => applyGroup(section));
        });
      }
      section.querySelectorAll("[data-switch]").forEach(el => {
        const idsCsv = el.getAttribute("data-switch") || "";
        idsCsv.split(",").map(s => s.trim()).filter(Boolean).forEach(id => {
          d.getElementById(id)?.addEventListener("change", () => applyGroup(section));
        });
      });
      applyGroup(section);
    }
    groups.forEach(attach);
  }
  if (d.readyState === "loading") d.addEventListener("DOMContentLoaded", bindDataToggles);
  else bindDataToggles();

})(window, document);
